import { Schema as S } from "effect"

export const DeliveryChannel = S.Literals(["email", "sms", "push"])

export const QuietHours = S.Struct({
  startHour: S.Number,
  endHour: S.Number,
  timeZone: S.String
})

export const DeliveryPreferences = S.Struct({
  accountId: S.String,
  primaryChannel: DeliveryChannel,
  fallbackChannel: DeliveryChannel.pipe(S.optionalKey),
  quietHours: QuietHours.pipe(S.NullOr),
  digestLabel: S.String.pipe(S.UndefinedOr),
  enabled: S.Boolean
})

export type DeliveryPreferences = typeof DeliveryPreferences.Type

export const decodeDeliveryPreferences = S.decodeUnknownSync(
  DeliveryPreferences
)

export const defaultPreferences: DeliveryPreferences = {
  accountId: "account-482",
  primaryChannel: "email",
  quietHours: null,
  digestLabel: undefined,
  enabled: true
}
